"""Freeze actual verified offline build evidence. No hardware or programming action."""
from pathlib import Path
import datetime,hashlib,importlib.util,json
ROOT=Path(__file__).resolve().parent
FIX=ROOT/'fixture'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def load(p):return json.loads(p.read_text(encoding='utf8'))
def main():
 spec=importlib.util.spec_from_file_location('release_builder',FIX/'build_project.py')
 b=importlib.util.module_from_spec(spec);spec.loader.exec_module(b)
 b.static_contract();q=load(ROOT/'qualification.json');m=load(FIX/'build_manifest.json')
 assert q.get('offline_tests_passed') is True and m.get('verified') is True
 assert q.get('programming_authorized') is False and m.get('programming_authorized') is False
 sources=b.source_hashes();assert q['sources_sha256']==m['sources_sha256']==sources
 evidence=q.get('evidence_sha256');assert isinstance(evidence,dict) and evidence
 for name,h in evidence.items():assert sha(ROOT/name)==h,('Qualification evidence changed',name)
 # Re-run actual mapped binding, freshness, PNR,17pins,timing and FS verification.
 actual=b.verify(sources)
 for key in ['verified','sources_sha256','bitstream','artifact_sha256','fmax_mhz','io_count','unrouted_nets','slack','pins','synthesis_options','synthesis_resources']:
  assert actual[key]==m[key],('Actual build evidence changed',key)
 assert actual['verified'] is True and actual['io_count']==17 and actual['pins']==b.PINS
 assert actual['fmax_mhz']>=50 and actual['unrouted_nets']==0
 assert all(actual['slack'][k]=={'tns_ns':0.0,'violated_endpoints':0}for k in ['setup','hold'])
 assert actual['mapped_init_review']['passed'] is True and actual['synthesis_freshness_review']['passed'] is True
 assert actual['programming_authorized'] is False and actual['flight_ready'] is False
 aggregate=load(ROOT/'hardware/mapped_init_review.json')
 assert aggregate.get('passed') is True and aggregate.get('sources_sha256')==sources
 assert aggregate.get('logical_bits_verified')==1696 and aggregate.get('nav_logical_bits')==720 and aggregate.get('mtf_logical_bits')==976
 aggregate_evidence=aggregate.get('evidence_sha256');assert isinstance(aggregate_evidence,dict) and aggregate_evidence
 for name in ['mapped_nav_review.json','mapped_mtf_review.json']:
  path=ROOT/'hardware'/name;review=load(path);assert review.get('passed') is True,('Current mapped audit missing',name)
  assert sha(path) in aggregate_evidence.values(),('Aggregate does not bind mapped report',name)
 for name,h in aggregate_evidence.items():
  path=Path(name);assert sha(path if path.is_absolute() else ROOT/path)==h,('Aggregate evidence changed',name)
 # Audit artifacts are regenerated by verify(); qualification must still bind every input.
 for name,h in evidence.items():assert sha(ROOT/name)==h,('Evidence changed during verification',name)
 files=['qualification.json','fixture/build_manifest.json','fixture/build_project.py','source_contract.json','control_contract.py','inherited_context_bridge.py','verify_mapped_binding.py','OPERATOR_NOTES.txt','finalize_release.py','hardware/mapped_init_review.json','hardware/mapped_nav_review.json','hardware/mapped_mtf_review.json','hardware/full_build_mapped_init_review.json','hardware/full_build_synthesis_freshness_review.json','hardware/review_synthesis_freshness.py']
 bindings={name:sha(ROOT/name)for name in files}
 parent=load(ROOT/'source_contract.json')['parent']
 report=dict(candidate='B0B0 MTF diagnostic startup reset',created_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),offline_verified=True,sources_sha256=sources,qualification_evidence_sha256=evidence,release_evidence_sha256=bindings,bitstream=actual['bitstream'],build_artifact_sha256=actual['artifact_sha256'],fmax_mhz=actual['fmax_mhz'],unrouted_nets=0,io_count=17,pins=actual['pins'],slack=actual['slack'],parent=parent,parent_status='Frozen prior candidate failed PNR with530unrouted nets and no FS; provenance only',hardware_programmed=False,flash_changed=False,flight_ready=False,programming_authorized=False,remaining=['Fresh stopped-device identity and explicitly authorized props-off SRAM acceptance','Healthy-height output regression; loss/manual/recovery/land_lock/SWA/RC/IMU acceptance','Historical4S loaded power-loss investigation and flight qualification'])
 # Preserve the established read-only installer release-binding interface.
 report.update(qualification_sha256=bindings['qualification.json'],build_manifest_sha256=bindings['fixture/build_manifest.json'],verifier_sha256=bindings['fixture/build_project.py'],source_contract_sha256=bindings['source_contract.json'],operator_notes_sha256=bindings['OPERATOR_NOTES.txt'])
 (ROOT/'offline_release.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf8');print(json.dumps(report,indent=2))
if __name__=='__main__':main()
